import { Accordion } from "@chakra-ui/react";
import { RasaCodeBlock } from "../../RasaCodeBlock";
import type { ConversationEvent } from "../../types";
import { CommonEventInfo, DetailView, EventAccordionItem, InfoField } from "./blocks";

interface PlainEventInfoProps {
  event: ConversationEvent;
  onClose: () => void;
}

export const PlainEventInfo = ({ event, onClose }: PlainEventInfoProps) => {
  const rawEvent = event.metadata.rawEvent;
  const eventFields = rawEvent ? omitMetadata(rawEvent) : omitMetadata(event);
  const metadata = rawEvent?.metadata ?? omitRawEvent(event.metadata);

  return (
    <DetailView title="Event" onClose={onClose}>
      <InfoField label="Event fields" data-testid="event-fields">
        <RasaCodeBlock code={formatJson(eventFields)} maxCodeHeight="64" />
      </InfoField>

      <InfoField label="Metadata" data-testid="event-metadata">
        <RasaCodeBlock code={formatJson(metadata)} maxCodeHeight="64" />
      </InfoField>

      <Accordion.Root collapsible multiple>
        <EventAccordionItem title="Event info" value="event-info">
          <CommonEventInfo event={event} />
        </EventAccordionItem>
      </Accordion.Root>
    </DetailView>
  );
};

function omitMetadata(value: object): object {
  const { metadata: _metadata, ...fields } = value as { metadata?: unknown } & object;
  return fields;
}

function omitRawEvent(metadata: ConversationEvent["metadata"]): object {
  const { rawEvent: _rawEvent, ...fields } = metadata;
  return fields;
}

function formatJson(value: unknown): string {
  return JSON.stringify(value, null, 2) ?? "—";
}
